export type GeneratedImageMimeType = 'image/png' | 'image/jpeg' | 'image/webp';
export type GeneratedImageFormat = 'png' | 'jpeg' | 'webp';

/** A pinned reference to immutable generated bytes, safe for saved chat state. */
export interface GeneratedImageReference { id: string; sha256: string }

/** Public metadata only. Image bytes and filesystem locations never belong here. */
export interface GeneratedImageMetadata extends GeneratedImageReference {
  workspaceId: string;
  threadId: string;
  messageId: string;
  runId: string;
  itemId: string;
  state: 'completed';
  mimeType: GeneratedImageMimeType;
  bytes: number;
  width: number;
  height: number;
  createdAt: string;
  previewUrl: string;
  /** Provider-public text, already redacted by the engine before committing. */
  revisedPrompt?: string;
}

/** Server-only input. Never serialize this object into activities or logs. */
export interface CommitGeneratedImageInput {
  workspaceId: string;
  threadId: string;
  messageId: string;
  runId: string;
  itemId: string;
  resultBase64: string;
  outputFormat?: GeneratedImageFormat;
  revisedPrompt?: string;
}

export interface GeneratedImageRead {
  metadata: GeneratedImageMetadata;
  /** Server-only bytes for verified model replay, workspace copies or downloads. */
  bytes: Buffer;
}

export interface GeneratedImageModelOptions {
  /** Require ownership by this thread; omit only for a validated explicit fork. */
  threadId?: string;
  detail?: 'high' | 'original';
  signal?: AbortSignal;
}
export interface GeneratedImageReadLeaseOptions {
  /** Omit only after independently verifying an explicit fork/delivered reference. */
  threadId?: string;
  signal?: AbortSignal;
}

export interface GeneratedImageServiceOptions { now?: () => number }
export interface GeneratedImageRecovery {
  removedTemporaryFiles: number;
  removedUncommittedImages: number;
  removedUncommittedRecords: number;
  removedDeletedWorkspaceFiles: number;
  retainedUnexpectedEntries: number;
}
export interface GeneratedImageWorkspaceCleanup {
  workspaceId: string;
  deletedFiles: number;
  /** Always true once the method returns; the fence survives process replacement. */
  permanentlyFenced: true;
}
